use verus::prelude::*;         // brings in `old`, `forall`, pervasive `Vec`, etc.

/// Swaps the first and last elements of `a` if it has length ≥ 2.
/// Otherwise leaves it unchanged.
///
/// Post‐condition:
/// * If the old vector `old(a)` had length ≥ 2, then for all indices i:
///     – at i == 0 we see `old(a)[old(a).len()-1]`,
///     – at i == old(a).len()-1 we see `old(a)[0]`,
///     – everywhere else it’s unchanged.
/// * If the old vector had length < 2, then `a` is unchanged.
#[requires(true)]
#[ensures(|a: &mut Vec<i32>| {
    let old_a = old(a);
    if old_a.len() >= 2 {
        // length unchanged
        a.len() == old_a.len()
        // elements swapped at 0 and len-1, everything else same
        && forall(|i: usize| i < a.len() ==>
            if i == 0 {
                a[i] == old_a[old_a.len() - 1]
            } else if i == a.len() - 1 {
                a[i] == old_a[0]
            } else {
                a[i] == old_a[i]
            })
    } else {
        // length < 2, unchanged
        *a == old_a
    }
})]
fn swap_first_and_last(a: &mut Vec<i32>) {
    let n = a.len();
    if n >= 2 {
        // help the verifier see that we can safely call swap(0, n-1)
        assert(n > 0);
        assert(n - 1 < a.len());
        a.swap(0, n - 1);
        // length must still be n
        assert(a.len() == n);
    }
}

fn main() {
    // Example usage
    let mut v1 = vec![1, 2, 3, 4, 5];
    swap_first_and_last(&mut v1);
    assert_eq!(v1, vec![5, 2, 3, 4, 1]);

    let mut v2 = vec![42];
    swap_first_and_last(&mut v2);
    assert_eq!(v2, vec![42]);

    println!("All tests passed!");
}